function countPalindromes(s) {
  const MOD = 1_000_000_007;
  const n = s.length;
  const digits = Array.from(s, ch => ch.charCodeAt(0) - 48);

  const after = new Array(n + 1);
  after[n] = new Array(100).fill(0);
  const seenAfter = new Array(10).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    after[i] = after[i + 1].slice();
    for (let d = 0; d < 10; d++) {
      after[i][digits[i] * 10 + d] += seenAfter[d];
    }
    seenAfter[digits[i]]++;
  }

  const before = new Array(100).fill(0);
  const seenBefore = new Array(10).fill(0);
  let answer = 0;
  for (let i = 0; i < n; i++) {
    for (let a = 0; a < 10; a++) {
      for (let b = 0; b < 10; b++) {
        answer = (answer + before[a * 10 + b] * after[i + 1][b * 10 + a]) % MOD;
      }
    }
    for (let d = 0; d < 10; d++) {
      before[d * 10 + digits[i]] += seenBefore[d];
    }
    seenBefore[digits[i]]++;
  }
  return answer;
}

