function countPalindromes(s) {
  // Count, for each of the 1000 palindromes "xyzyx", how many ways it appears as a subsequence.
  const MOD = 1000000007;
  let total = 0;
  for (let p = 0; p < 1000; p++) {
    const x = String(Math.floor(p / 100)), y = String(Math.floor(p / 10) % 10), z = String(p % 10);
    const pattern = x + y + z + y + x;
    const ways = [1, 0, 0, 0, 0, 0];
    for (const ch of s)
      for (let j = 5; j >= 1; j--)
        if (pattern[j - 1] === ch) ways[j] = (ways[j] + ways[j - 1]) % MOD;
    total = (total + ways[5]) % MOD;
  }
  return total;
}

