function generate(rand, size) {
  const alphabet = Math.floor(rand() * 10) + 1;
  const offset = Math.floor(rand() * (11 - alphabet));
  const n = size === 'large' ? 10000 : 1 + Math.floor(rand() * 14);
  let s = '';
  for (let i = 0; i < n; i++) s += String(offset + Math.floor(rand() * alphabet));
  return [s];
}
